REM Virtual columns, row-level and fine-grained auditing policies, and views over views, each over a sequence of its own.
set feedback on echo on pagesize 100 linesize 160
whenever sqlerror continue
CREATE USER APP_R3 IDENTIFIED BY "not-a-real-password";
GRANT CREATE SESSION TO APP_R3;
ALTER USER APP_R3 READ ONLY;
CREATE SEQUENCE APP_OWNER.S_VC NOCACHE;
CREATE SEQUENCE APP_OWNER.S_FBI NOCACHE;
CREATE SEQUENCE APP_OWNER.S_POL NOCACHE;
CREATE SEQUENCE APP_OWNER.S_FGA NOCACHE;
CREATE SEQUENCE APP_OWNER.S_NEST NOCACHE;
CREATE SEQUENCE APP_OWNER.S_BEHIND NOCACHE;
CREATE SEQUENCE APP_OWNER.S_INV NOCACHE;
CREATE OR REPLACE FUNCTION APP_OWNER.F_VC(x NUMBER) RETURN NUMBER DETERMINISTIC AS BEGIN RETURN APP_OWNER.S_VC.NEXTVAL; END;
/
CREATE OR REPLACE FUNCTION APP_OWNER.F_FBI(x NUMBER) RETURN NUMBER DETERMINISTIC AS BEGIN RETURN APP_OWNER.S_FBI.NEXTVAL; END;
/
CREATE OR REPLACE FUNCTION APP_OWNER.F_INV(x NUMBER) RETURN NUMBER DETERMINISTIC AS BEGIN RETURN APP_OWNER.S_INV.NEXTVAL; END;
/
CREATE OR REPLACE FUNCTION APP_OWNER.F_NEST RETURN NUMBER AS BEGIN RETURN APP_OWNER.S_NEST.NEXTVAL; END;
/
CREATE OR REPLACE FUNCTION APP_OWNER.F_POL(s VARCHAR2, o VARCHAR2) RETURN VARCHAR2 AS n NUMBER; BEGIN n := APP_OWNER.S_POL.NEXTVAL; RETURN NULL; END;
/
CREATE OR REPLACE FUNCTION APP_OWNER.F_BEHIND(s VARCHAR2, o VARCHAR2) RETURN VARCHAR2 AS n NUMBER; BEGIN n := APP_OWNER.S_BEHIND.NEXTVAL; RETURN NULL; END;
/
CREATE OR REPLACE PROCEDURE APP_OWNER.H_FGA(s VARCHAR2, o VARCHAR2, p VARCHAR2) AS n NUMBER; BEGIN n := APP_OWNER.S_FGA.NEXTVAL; END;
/
REM A virtual column over a function and one over a built-in.
CREATE TABLE APP_OWNER.R3_VC (ID NUMBER, N NUMBER GENERATED ALWAYS AS (APP_OWNER.F_VC(ID)) VIRTUAL, U VARCHAR2(50) GENERATED ALWAYS AS (UPPER('a' || TO_CHAR(ID))) VIRTUAL);
INSERT INTO APP_OWNER.R3_VC (ID) VALUES (1);
REM Function-based indexes: their hidden virtual columns.
CREATE TABLE APP_OWNER.R3_FBI (ID NUMBER, NAME VARCHAR2(20));
INSERT INTO APP_OWNER.R3_FBI VALUES (1, 'x');
CREATE INDEX APP_OWNER.R3_FBI_UP ON APP_OWNER.R3_FBI (UPPER(NAME));
CREATE INDEX APP_OWNER.R3_FBI_F ON APP_OWNER.R3_FBI (APP_OWNER.F_FBI(ID));
REM A row-level policy on a table, on a private synonym and on a PUBLIC synonym; one on a table read only through a view.
CREATE TABLE APP_OWNER.R3_POL (ID NUMBER);
INSERT INTO APP_OWNER.R3_POL VALUES (1);
CREATE TABLE APP_OWNER.R3_SYNPOL (ID NUMBER);
INSERT INTO APP_OWNER.R3_SYNPOL VALUES (1);
CREATE SYNONYM APP_OWNER.R3_SYNPOL_S FOR APP_OWNER.R3_SYNPOL;
CREATE PUBLIC SYNONYM R3_SYNPOL_P FOR APP_OWNER.R3_SYNPOL;
CREATE TABLE APP_OWNER.R3_BEHIND (ID NUMBER);
INSERT INTO APP_OWNER.R3_BEHIND VALUES (1);
CREATE VIEW APP_OWNER.R3_BEHIND_V AS SELECT ID FROM APP_OWNER.R3_BEHIND;
REM A fine-grained auditing handler on a table.
CREATE TABLE APP_OWNER.R3_FGA (ID NUMBER);
INSERT INTO APP_OWNER.R3_FGA VALUES (1);
REM A view over a view, the inner one replaced to call a function after the outer one was created.
CREATE VIEW APP_OWNER.R3_INNER AS SELECT 1 AS N FROM DUAL;
CREATE VIEW APP_OWNER.R3_OUTER AS SELECT N FROM APP_OWNER.R3_INNER;
CREATE OR REPLACE VIEW APP_OWNER.R3_INNER AS SELECT APP_OWNER.F_NEST() AS N FROM DUAL;
CREATE TABLE APP_OWNER.R3_INV (ID NUMBER, N NUMBER);
INSERT INTO APP_OWNER.R3_INV (ID, N) VALUES (1, 0);
CREATE VIEW APP_OWNER.R3_INV_V AS SELECT ID, N FROM APP_OWNER.R3_INV;
COMMIT;
BEGIN
  DBMS_RLS.ADD_POLICY(object_schema => 'APP_OWNER', object_name => 'R3_POL', policy_name => 'R3_POL_P',
    function_schema => 'APP_OWNER', policy_function => 'F_POL', statement_types => 'SELECT');
  DBMS_RLS.ADD_POLICY(object_schema => 'APP_OWNER', object_name => 'R3_SYNPOL_S', policy_name => 'R3_SYN_P',
    function_schema => 'APP_OWNER', policy_function => 'F_POL', statement_types => 'SELECT');
  DBMS_RLS.ADD_POLICY(object_schema => 'PUBLIC', object_name => 'R3_SYNPOL_P', policy_name => 'R3_PSYN_P',
    function_schema => 'APP_OWNER', policy_function => 'F_POL', statement_types => 'SELECT');
  DBMS_RLS.ADD_POLICY(object_schema => 'APP_OWNER', object_name => 'R3_BEHIND', policy_name => 'R3_BEHIND_P',
    function_schema => 'APP_OWNER', policy_function => 'F_BEHIND', statement_types => 'SELECT');
  DBMS_FGA.ADD_POLICY(object_schema => 'APP_OWNER', object_name => 'R3_FGA', policy_name => 'R3_FGA_P',
    handler_schema => 'APP_OWNER', handler_module => 'H_FGA', statement_types => 'SELECT');
END;
/
GRANT SELECT ON APP_OWNER.R3_VC TO APP_R3;
GRANT SELECT ON APP_OWNER.R3_FBI TO APP_R3;
GRANT SELECT ON APP_OWNER.R3_POL TO APP_R3;
GRANT SELECT ON APP_OWNER.R3_SYNPOL TO APP_R3;
GRANT SELECT ON APP_OWNER.R3_BEHIND_V TO APP_R3;
GRANT SELECT ON APP_OWNER.R3_FGA TO APP_R3;
GRANT SELECT ON APP_OWNER.R3_OUTER TO APP_R3;
GRANT SELECT ON APP_OWNER.R3_INV_V TO APP_R3;
REM A view left invalid after its grant: the column it reads dropped and re-added as a virtual column over a function.
ALTER TABLE APP_OWNER.R3_INV DROP COLUMN N;
ALTER TABLE APP_OWNER.R3_INV ADD (N NUMBER GENERATED ALWAYS AS (APP_OWNER.F_INV(ID)) VIRTUAL);
col object_name format a16
SELECT OBJECT_NAME, STATUS FROM DBA_OBJECTS WHERE OWNER = 'APP_OWNER' AND OBJECT_NAME IN ('R3_OUTER', 'R3_INV_V') ORDER BY 1;
col sequence_name format a12
SELECT SEQUENCE_NAME, LAST_NUMBER FROM DBA_SEQUENCES WHERE SEQUENCE_OWNER = 'APP_OWNER' AND SEQUENCE_NAME LIKE 'S\_%' ESCAPE '\' ORDER BY 1;
